import json,hashlib,os,subprocess,sys,shutil,time
ROOT=Path(r'C:\KatarinaGitTest-4e14b098');STATE=Path(r'C:\KatarinaDev\state\owner-broker-readonly\readonly-observer')
PAYLOAD=json.loads('{"src/katarina/intelligence/autonomous_research.py": "\\"\\"\\"Bounded cached-data research worker. No broker, model, network or order access.\\"\\"\\"\\nfrom contextlib import closing\\nfrom datetime import datetime, timezone\\nfrom hashlib import sha256\\nfrom itertools import product\\nimport json\\nfrom pathlib import Path\\nimport os\\nfrom katarina.monitoring.snapshot_io import replace_snapshot\\nimport sqlite3\\nimport threading\\nimport zlib\\n\\nGRID = tuple(product((\'MOMENTUM\',\'MEAN_REVERSION\',\'BREAKOUT\'), (1,-1), (12,24,48), (4,12,24), (.5,1.,1.5)))\\nVERSION = \'cached-entry-grid-v1\'\\n\\n\\ndef preserve_dataset(db, digest, rows):\\n    \\"\\"\\"Freeze exact experiment inputs once; shared digest avoids per-trial copies.\\"\\"\\"\\n    db.execute(\'CREATE TABLE IF NOT EXISTS research_datasets(digest TEXT PRIMARY KEY,rows_zlib BLOB NOT NULL)\')\\n    if db.execute(\'SELECT 1 FROM research_datasets WHERE digest=?\',(digest,)).fetchone():return\\n    payload=json.dumps(rows,separators=(\',\',\':\')).encode()\\n    if len(payload)>2_000_000 or sha256(payload).hexdigest()!=digest:\\n        raise ValueError(\'DATASET_INTEGRITY_FAILED\')\\n    db.execute(\'INSERT OR IGNORE INTO research_datasets VALUES(?,?)\',(digest,zlib.compress(payload)))\\n\\n\\ndef preserved_dataset(db, digest):\\n    if not db.execute(\\"SELECT 1 FROM sqlite_master WHERE type=\'table\' AND name=\'research_datasets\'\\").fetchone():return None\\n    stored=db.execute(\'SELECT rows_zlib FROM research_datasets WHERE digest=?\',(digest,)).fetchone()\\n    if stored is None:return None\\n    decoder=zlib.decompressobj();payload=decoder.decompress(stored[0],2_000_001)\\n    if len(payload)>2_000_000 or not decoder.eof or sha256(payload).hexdigest()!=digest:\\n        raise ValueError(\'DATASET_INTEGRITY_FAILED\')\\n    rows=json.loads(payload)\\n    if not isinstance(rows,list) or not 512<=len(rows)<=8192:raise ValueError(\'DATASET_SHAPE_FAILED\')\\n    return rows\\n\\n\\ndef cost_review(rows, original, level):\\n    cfg=(original[\'method\'],1 if original[\'side\']==\'BUY\' else -1,original[\'lookback\'],original[\'horizon\'],original[\'threshold\'])\\n    result=evaluate(rows,cfg,original[\'spread_proxy_price\']*level,range_cost=.2*level)\\n    result[\'stress_cost_multiplier\']=level\\n    return result\\n\\n\\ndef evaluate(rows, config, spread, range_cost=.2):\\n    family, side, lookback, horizon, threshold = config\\n    split = len(rows)*2//3\\n    samples = [[], []]\\n    for i in range(max(lookback,14), len(rows)-horizon, horizon+1):\\n        prior = rows[i-lookback:i]\\n        scale = sum(r[2]-r[3] for r in rows[i-14:i])/14\\n        if scale <= 0: continue\\n        close = rows[i][4]\\n        signal = ((close-prior[0][4])*side > threshold*scale if family==\'MOMENTUM\' else\\n                  (sum(r[4] for r in prior)/lookback-close)*side > threshold*scale if family==\'MEAN_REVERSION\' else\\n                  close > max(r[2] for r in prior)+(threshold-.5)*scale if side==1 else\\n                  close < min(r[3] for r in prior)-(threshold-.5)*scale)\\n        if not signal: continue\\n        # Require consecutive H1 bars throughout entry/exit; weekend/gap trades excluded.\\n        if any(rows[j+1][0]-rows[j][0] != 3600 for j in range(i,i+horizon)): continue\\n        bucket = 0 if i+horizon < split else 1 if i >= split else None\\n        if bucket is not None:\\n            samples[bucket].append(((rows[i+horizon][4]-rows[i+1][1])*side-spread-range_cost*scale)/scale)\\n    def metrics(values):\\n        loss = -sum(x for x in values if x<0)\\n        return dict(n=len(values),mean_range_units=sum(values)/len(values) if values else None,\\n                    win_rate=sum(x>0 for x in values)/len(values) if values else None,\\n                    profit_factor=sum(x for x in values if x>0)/loss if loss else None)\\n    dev, review = map(metrics,samples)\\n    assessment=(\'INSUFFICIENT_SAMPLES\' if min(dev[\'n\'],review[\'n\'])<30 else\\n                \'REJECTED_IN_HISTORICAL_REVIEW\' if dev[\'mean_range_units\']<=0 or review[\'mean_range_units\']<=0 else\\n                \'NEEDS_FORWARD_VALIDATION\')\\n    return dict(method=family,side=\'BUY\' if side==1 else \'SELL\',lookback=lookback,horizon=horizon,threshold=threshold,\\n                development=dev,review=review,review_is_chronological=True,independent_holdout=False,\\n                history_reused=True,execution_model=\'NEXT_H1_OPEN_FIXED_CLOSE_NO_SL_TP\',\\n                cost_model=f\'RECORDED_CURRENT_SPREAD_PLUS_{range_cost:.2f}_MEAN_RANGE\',\\n                status=assessment,live_authorized=False,improvement_verified=False)\\n\\n\\nclass ResearchWorker:\\n    def __init__(self, root, trace, family=None, horizon=None):\\n        self.root=Path(root);self.trace=trace;self.stop=threading.Event()\\n        self.family=family\\n        self.horizon=horizon\\n        self.phase={None:\\"EXPERIMENT\\",\\"MOMENTUM\\":\\"TEST_MOMENTUM\\",\\"MEAN_REVERSION\\":\\"TEST_REVERSION\\",\\"BREAKOUT\\":\\"TEST_BREAKOUT\\"}[family]\\n        if horizon is not None:self.phase += \'_H\'+str(horizon)\\n        self.thread=threading.Thread(target=self.run,name=self.phase.lower(),daemon=True)\\n        self.state={\'status\':\'STARTING\',\'completed\':0,\'live_authorized\':False}\\n\\n    def start(self):\\n        self.thread.start();return self\\n\\n    def close(self):\\n        self.stop.set();self.thread.join(timeout=15)\\n        if self.thread.is_alive(): raise RuntimeError(\'RESEARCH_WORKER_STOP_TIMEOUT\')\\n\\n    def tick(self):\\n        from katarina.intelligence.research_capacity import research_capacity\\n        capacity=research_capacity(self.root)\\n        self.state[\'capacity\']=capacity\\n        if capacity[\'status\']!=\'READY\':\\n            self.state[\'status\']=capacity[\'status\'];return False\\n        target=self.root/\'experiment-jobs.sqlite3\'\\n        with closing(sqlite3.connect(target,timeout=2)) as jobs:\\n            jobs.execute(\'CREATE TABLE IF NOT EXISTS trials(id TEXT PRIMARY KEY,symbol TEXT,digest TEXT,created_utc TEXT,result_json TEXT)\')\\n            jobs.execute(\\"CREATE INDEX IF NOT EXISTS trials_role ON trials(json_extract(result_json,\'$.method\'),json_extract(result_json,\'$.horizon\'))\\")\\n            # A separate read-only connection; canonical observer retains exclusive broker ownership.\\n            with closing(sqlite3.connect((self.root/\'context.sqlite3\').as_uri()+\'?mode=ro\',uri=True,timeout=2)) as data:\\n                symbols=data.execute(\'SELECT symbol FROM lab_universe ORDER BY symbol\').fetchall()\\n                done=jobs.execute(\'SELECT COUNT(*) FROM trials\').fetchone()[0]\\n                role_done=jobs.execute(\\"SELECT COUNT(*) FROM trials WHERE json_extract(result_json,\'$.method\')=?\\",(self.family,)).fetchone()[0] if self.family else done\\n                if self.horizon is not None:\\n                    role_done=jobs.execute(\\"SELECT COUNT(*) FROM trials WHERE json_extract(result_json,\'$.method\')=? AND json_extract(result_json,\'$.horizon\')=?\\",(self.family,self.horizon)).fetchone()[0]\\n                for offset in range(len(symbols)):\\n                    symbol=symbols[(done+offset)%len(symbols)][0]\\n                    rows=data.execute(\'SELECT stamp,o,h,l,c FROM lab_bars WHERE symbol=? ORDER BY stamp DESC LIMIT 8192\',(symbol,)).fetchall()[::-1]\\n                    if len(rows)<512: continue\\n                    last=data.execute(\'SELECT result_json FROM lab_runs WHERE symbol=? ORDER BY created_utc DESC LIMIT 1\',(symbol,)).fetchone()\\n                    if not last: continue\\n                    spread=json.loads(last[0]).get(\'spread_proxy_price\')\\n                    if not isinstance(spread,(int,float)) or spread<0: continue\\n                    digest=sha256(json.dumps(rows,separators=(\',\',\':\')).encode()).hexdigest()\\n                    for config in GRID:\\n                        if self.family is not None and config[0]!=self.family: continue\\n                        if self.horizon is not None and config[3]!=self.horizon: continue\\n                        if self.stop.is_set(): return False\\n                        ident=sha256(json.dumps([VERSION,symbol,digest,config,spread]).encode()).hexdigest()\\n                        if jobs.execute(\'SELECT 1 FROM trials WHERE id=?\',(ident,)).fetchone(): continue\\n                        self.state.update(status=\'EXPERIMENTING\',completed=role_done)\\n                        self.trace.emit(self.phase,\'STARTED\',action=\'AUTONOMOUS_CACHED_RESEARCH\',method=config[0],symbol=symbol)\\n                        try:\\n                            result=evaluate(rows,config,spread)\\n                            result[\\"spread_proxy_price\\"]=spread\\n                            with jobs:\\n                                preserve_dataset(jobs,digest,rows)\\n                                result[\'dataset_preserved\']=True\\n                                jobs.execute(\'INSERT OR IGNORE INTO trials VALUES(?,?,?,?,?)\',(ident,symbol,digest,datetime.now(timezone.utc).isoformat(),json.dumps(result,allow_nan=False)))\\n                        except Exception:\\n                            self.trace.emit(self.phase,\'FAILED\',action=\'AUTONOMOUS_CACHED_RESEARCH\',symbol=symbol)\\n                            raise\\n                        self.trace.emit(self.phase,\'DONE\',action=\'AUTONOMOUS_CACHED_RESEARCH\',method=config[0],symbol=symbol,count=1)\\n                        self.state.update(status=\'EXPERIMENT_COMPLETED\',completed=role_done+1)\\n                        return True\\n        self.state.update(status=\'WAITING_NEW_DATA\',completed=role_done)\\n        return False\\n\\n    def run(self):\\n        while not self.stop.is_set():\\n            try:\\n                worked=self.tick()\\n            except sqlite3.OperationalError:\\n                self.state[\'status\']=\'WAITING_DATA_OR_DATABASE\';worked=False\\n            except Exception:\\n                self.state[\'status\']=\'RETRY_PENDING\';worked=False\\n            payload=dict(self.state,pid=os.getpid(),autonomous=True,as_of_utc=datetime.now(timezone.utc).isoformat(),grid_size=len(GRID))\\n            try:\\n                name=\'multitask-status\' if self.family is None else \'worker-\'+self.phase\\n                temp=self.root/(name+\'.tmp\')\\n                temp.write_text(json.dumps(payload)+\'\\\\n\',encoding=\'utf-8\');replace_snapshot(temp,self.root/(name+\'.json\'))\\n            except OSError: pass\\n            # Bounded pace, no expensive model calls or busy looping when all jobs are exhausted.\\n            self.stop.wait(2 if worked else 10)\\n\\n\\nclass ResearchPool:\\n    \\"\\"\\"Nine disjoint pattern/horizon experiments, two cost reviews and Gemini ideation.\\"\\"\\"\\n    def __init__(self,root,trace,model=None):\\n        self.root=Path(root);self.trace=trace;self.model=model\\n        self.stop=threading.Event();self.state={\'status\':\'STARTING\',\'completed\':0,\'live_authorized\':False}\\n        self.workers=[ResearchWorker(root,trace,f,h) for f in (\'MOMENTUM\',\'MEAN_REVERSION\',\'BREAKOUT\') for h in (4,12,24)]\\n        self.review_thread=threading.Thread(target=self.review_loop,args=(2,),name=\'cost-stress-2x\',daemon=True)\\n        self.stress_thread=threading.Thread(target=self.review_loop,args=(3,),name=\'cost-stress-3x\',daemon=True)\\n        self.model_thread=threading.Thread(target=self.model_loop,name=\'gemini-hypotheses\',daemon=True)\\n        self.thread=threading.Thread(target=self.run,name=\'research-coordinator\',daemon=True)\\n        self.review_states={level:{\'status\':\'STARTING\',\'completed\':0} for level in (2,3)}\\n        self.model_state={\'status\':\'WAITING_BUDGET\' if model is not None else \'NOT_CONFIGURED\',\'successful_calls\':0,\'failed_calls\':0}\\n\\n    @property\\n    def background_count(self):\\n        return sum(t.is_alive() for t in [self.thread,self.review_thread,self.stress_thread,self.model_thread]+[w.thread for w in self.workers])\\n\\n    def start(self):\\n        for w in self.workers:w.start()\\n        self.review_thread.start();self.stress_thread.start();self.model_thread.start();self.thread.start();return self\\n\\n    def close(self):\\n        self.stop.set()\\n        for w in self.workers:w.stop.set()\\n        for t in [self.thread,self.review_thread,self.stress_thread,self.model_thread]+[w.thread for w in self.workers]:t.join(timeout=65)\\n        if self.background_count:raise RuntimeError(\'RESEARCH_POOL_STOP_TIMEOUT\')\\n\\n    def _publish_role(self,phase,state):\\n        payload=dict(state,pid=os.getpid(),phase=phase,autonomous=True,as_of_utc=datetime.now(timezone.utc).isoformat())\\n        try:\\n            temp=self.root/(\'worker-\'+phase+\'.tmp\');temp.write_text(json.dumps(payload)+\'\\\\n\',encoding=\'utf-8\');replace_snapshot(temp,self.root/(\'worker-\'+phase+\'.json\'))\\n        except OSError:pass\\n\\n    def review_one(self, level=2):\\n        from katarina.intelligence.research_capacity import research_capacity\\n        capacity=research_capacity(self.root);state=self.review_states[level]\\n        if capacity[\'status\']!=\'READY\':\\n            state[\'status\']=capacity[\'status\'];return False\\n        phase=\\"VALIDATE\\" if level==2 else \\"VALIDATE3\\"\\n        prefix=\\"\\" if level==2 else \\"COST3:\\"\\n        with closing(sqlite3.connect(self.root/\'experiment-jobs.sqlite3\',timeout=2)) as db:\\n            db.execute(\'CREATE TABLE IF NOT EXISTS stress_reviews(trial_id TEXT PRIMARY KEY,created_utc TEXT,result_json TEXT)\')\\n            if not db.execute(\\"SELECT 1 FROM sqlite_master WHERE type=\'table\' AND name=\'trials\'\\").fetchone():return False\\n            frozen=db.execute(\\"SELECT 1 FROM sqlite_master WHERE type=\'table\' AND name=\'research_datasets\'\\").fetchone()\\n            priority=\\"CASE WHEN json_extract(result_json,\'$.status\')=\'NEEDS_FORWARD_VALIDATION\' THEN 0 ELSE 1 END,\\"\\n            if frozen:priority+=\'CASE WHEN t.digest IN (SELECT digest FROM research_datasets) THEN 0 ELSE 1 END,\'\\n            trial=db.execute(\\"SELECT id,symbol,digest,result_json FROM trials t WHERE json_extract(t.result_json,\'$.status\')=\'NEEDS_FORWARD_VALIDATION\' AND NOT EXISTS (SELECT 1 FROM stress_reviews s WHERE s.trial_id=?||t.id) ORDER BY \\"+priority+\'created_utc LIMIT 1\',(prefix,)).fetchone()\\n            if not trial:state[\'status\']=\'WAITING_ELIGIBLE_CANDIDATE\';return False\\n            state[\'status\']=\'REVIEWING\';self._publish_role(phase,state)\\n            self.trace.emit(phase,\'STARTED\',action=\'COST_STRESS_\'+str(level)+\'X\')\\n            original=json.loads(trial[3]);rows=preserved_dataset(db,trial[2]);source=\'FROZEN_EXPERIMENT_SNAPSHOT\'\\n            if rows is None:\\n                with closing(sqlite3.connect((self.root/\'context.sqlite3\').as_uri()+\'?mode=ro\',uri=True,timeout=2)) as data:\\n                    rows=data.execute(\'SELECT stamp,o,h,l,c FROM lab_bars WHERE symbol=? ORDER BY stamp DESC LIMIT 8192\',(trial[1],)).fetchall()[::-1]\\n                if sha256(json.dumps(rows,separators=(\',\',\':\')).encode()).hexdigest()!=trial[2]:rows=None\\n                source=\'CURRENT_CACHE_EXACT_MATCH\'\\n            if rows is None:result={\'status\':\'DATASET_CHANGED_REVIEW_UNAVAILABLE\',\'live_authorized\':False}\\n            else:\\n                result=cost_review(rows,original,level);result[\'dataset_source\']=source\\n            with db:db.execute(\'INSERT OR IGNORE INTO stress_reviews VALUES(?,?,?)\',(prefix+trial[0],datetime.now(timezone.utc).isoformat(),json.dumps(result,allow_nan=False)))\\n            self.trace.emit(phase,\'DONE\',count=1)\\n            state.update(status=\'REVIEW_COMPLETED\',completed=state[\'completed\']+1)\\n            return True\\n\\n    def repair_one(self):\\n        \\"\\"\\"Retry a failed legacy review only when its exact original dataset exists.\\"\\"\\"\\n        from katarina.intelligence.research_capacity import research_capacity\\n        if research_capacity(self.root)[\'status\']!=\'READY\':return False\\n        with closing(sqlite3.connect(self.root/\'experiment-jobs.sqlite3\',timeout=2)) as db:\\n            db.execute(\'CREATE TABLE IF NOT EXISTS research_repairs(id TEXT PRIMARY KEY,created_utc TEXT,result_json TEXT)\')\\n            if not db.execute(\\"SELECT 1 FROM sqlite_master WHERE type=\'table\' AND name=\'research_datasets\'\\").fetchone():return False\\n            row=db.execute(\\"SELECT s.trial_id,t.digest,t.result_json FROM stress_reviews s JOIN trials t ON t.id=CASE WHEN s.trial_id LIKE \'COST3:%\' THEN substr(s.trial_id,7) ELSE s.trial_id END JOIN research_datasets d ON d.digest=t.digest WHERE json_extract(s.result_json,\'$.status\')=\'DATASET_CHANGED_REVIEW_UNAVAILABLE\' AND json_extract(t.result_json,\'$.status\')=\'NEEDS_FORWARD_VALIDATION\' ORDER BY s.created_utc LIMIT 1\\").fetchone()\\n            if row is None:return False\\n            rows=preserved_dataset(db,row[1]);original=json.loads(row[2])\\n            self.trace.emit(\'LEARNING_REVIEW\',\'STARTED\',action=\'REPAIR_EXACT_DATASET_REVIEW\')\\n            result=cost_review(rows,original,3 if row[0].startswith(\'COST3:\') else 2)\\n            result[\'dataset_source\']=\'FROZEN_EXPERIMENT_SNAPSHOT\';result[\'recovered_from\']=\'DATASET_CHANGED_REVIEW_UNAVAILABLE\'\\n            stamp=datetime.now(timezone.utc).isoformat()\\n            with db:\\n                db.execute(\'UPDATE stress_reviews SET result_json=? WHERE trial_id=?\',(json.dumps(result,allow_nan=False),row[0]))\\n                db.execute(\'INSERT OR IGNORE INTO research_repairs VALUES(?,?,?)\',(row[0],stamp,json.dumps({\'action\':\'RESTORED_EXACT_DATASET_REVIEW\',\'previous_status\':\'DATASET_CHANGED_REVIEW_UNAVAILABLE\',\'new_status\':result[\'status\'],\'live_authorized\':False})))\\n            self.trace.emit(\'LEARNING_REVIEW\',\'DONE\',action=\'REPAIR_EXACT_DATASET_REVIEW\',count=1)\\n            return True\\n\\n    def review_loop(self,level=2):\\n        while not self.stop.is_set():\\n            try:worked=self.review_one(level)\\n            except Exception:\\n                self.review_states[level][\'status\']=\'RETRY_PENDING\'\\n                self.trace.emit(\'VALIDATE\' if level==2 else \'VALIDATE3\',\'FAILED\',action=\'RETRY_PENDING\');worked=False\\n            self._publish_role(\'VALIDATE\' if level==2 else \'VALIDATE3\',self.review_states[level])\\n            self.stop.wait(15 if worked else 30)\\n\\n    def model_once(self):\\n        if self.model is None:return False\\n        from katarina.intelligence.research_capacity import research_capacity\\n        capacity=research_capacity(self.root)\\n        if capacity[\'status\']!=\'READY\':self.model_state[\'status\']=capacity[\'status\'];return False\\n        target=self.root/\'gemini-research.json\'\\n        try:\\n            old=json.loads(target.read_text())\\n            if (datetime.now(timezone.utc)-datetime.fromisoformat(old[\'attempt_utc\'])).total_seconds()<300:return False\\n        except (OSError,ValueError,KeyError):pass\\n        stamp=datetime.now(timezone.utc).isoformat()\\n        # Persist attempt before API call: restarts cannot bypass the five-minute budget.\\n        target.write_text(json.dumps({\'attempt_utc\':stamp,\'status\':\'STARTED\'})+\'\\\\n\')\\n        self.trace.emit(\'GEMINI\',\'STARTED\',action=\'PUBLIC_PATTERN_HYPOTHESES\')\\n        try:\\n            with closing(sqlite3.connect(self.root/\'experiment-jobs.sqlite3\',timeout=2)) as db:\\n                db.execute(\'CREATE TABLE IF NOT EXISTS gemini_hypotheses(created_utc TEXT PRIMARY KEY,result_json TEXT)\')\\n                previous=db.execute(\'SELECT result_json FROM gemini_hypotheses ORDER BY created_utc DESC LIMIT 2\').fetchall()\\n            topics=(\'pullback\',\'liquidity sweep\',\'breakout\',\'trend continuation\',\'range rejection\',\'failed breakout\')\\n            topic=topics[int(datetime.now(timezone.utc).timestamp()//300)%len(topics)]\\n            context=\' Focus: \'+topic+\'. Avoid repeating these previous public hypotheses: \'+json.dumps(previous)[:6000]\\n            reply=self.model.complete([{\'role\':\'system\',\'content\':\'You are a market research hypothesis writer. Return valid JSON only, at most 150 words. Do not provide orders, code, instrument-specific advice or claim validation.\'},{\'role\':\'user\',\'content\':\'Propose ONE falsifiable entry-pattern hypothesis. Return exactly six short string fields: pattern, signal_definition, invalidation, required_data, failure_mode, validation_plan. Distinguish assumptions from evidence. This is research only.\'+context}],mode=\'fast\')\\n            target.write_text(json.dumps({\'attempt_utc\':stamp,\'status\':\'HYPOTHESES_ONLY\',\'hypotheses\':reply,\'live_authorized\':False},allow_nan=False)+\'\\\\n\')\\n            with closing(sqlite3.connect(self.root/\'experiment-jobs.sqlite3\',timeout=2)) as db, db:\\n                db.execute(\'INSERT OR IGNORE INTO gemini_hypotheses VALUES(?,?)\',(stamp,json.dumps(reply,allow_nan=False)))\\n            self.model_state.update(status=\'HYPOTHESES_SAVED\' ,**self.model.telemetry())\\n            self.trace.emit(\'GEMINI\',\'DONE\',action=\'HYPOTHESES_REQUIRE_IMPLEMENTATION_AND_TESTS\')\\n        except Exception:\\n            self.model_state.update(status=\'RETRY_AFTER_COOLDOWN\',**self.model.telemetry())\\n            target.write_text(json.dumps({\'attempt_utc\':stamp,\'status\':\'RETRY_AFTER_COOLDOWN\',\'live_authorized\':False})+\'\\\\n\')\\n            self.trace.emit(\'GEMINI\',\'FAILED\',action=\'RETRY_AFTER_COOLDOWN\')\\n        return True\\n\\n    def model_loop(self):\\n        while not self.stop.is_set():\\n            try:self.model_once()\\n            except Exception:self.model_state[\'status\']=\'RETRY_AFTER_COOLDOWN\'\\n            self._publish_role(\'GEMINI\',self.model_state)\\n            self.stop.wait(5)\\n\\n    def run(self):\\n        next_repair=0;next_reports=0\\n        while not self.stop.is_set():\\n            try:\\n                import time\\n                if time.monotonic()>=next_repair:\\n                    next_repair=time.monotonic()+30\\n                    try:self.repair_one()\\n                    except Exception:\\n                        self.trace.emit(\'LEARNING_REVIEW\',\'FAILED\',action=\'REPAIR_RETRY_PENDING\')\\n                if time.monotonic()>=next_reports:\\n                    next_reports=time.monotonic()+3\\n                    try:\\n                        from katarina.intelligence.research_reports import publish_reports\\n                        publish_reports(self.root,self.trace)\\n                    except Exception:self.trace.emit(\'REPORT\',\'FAILED\',action=\'REPORT_RETRY_PENDING\')\\n                with closing(sqlite3.connect(self.root/\'experiment-jobs.sqlite3\',timeout=2)) as db:\\n                    count=db.execute(\'SELECT COUNT(*) FROM trials\').fetchone()[0]\\n                    reviews=db.execute(\'SELECT COUNT(*) FROM stress_reviews\').fetchone()[0]\\n                self.state.update(status=\'RUNNING\',completed=count,stress_reviews=reviews,background_workers=self.background_count,\\n                                  research_workers=12,workers=[dict(w.state,role=w.family,phase=w.phase,horizon=w.horizon) for w in self.workers],gemini=dict(self.model_state))\\n                temp=self.root/\'multitask-status.tmp\';temp.write_text(json.dumps(dict(self.state,as_of_utc=datetime.now(timezone.utc).isoformat(),grid_size=len(GRID)))+\'\\\\n\');replace_snapshot(temp,self.root/\'multitask-status.json\')\\n            except (sqlite3.Error,OSError):pass\\n            self.stop.wait(1)\\n\\n", "src/katarina/intelligence/research_reports.py": "\\"\\"\\"Durable rule-based experiment decisions. No broker, model, orders or promotion.\\"\\"\\"\\nfrom katarina.monitoring.snapshot_io import replace_snapshot\\nfrom contextlib import closing\\nfrom datetime import datetime, timezone\\nfrom hashlib import sha256\\nimport json\\nimport math\\nimport os\\nfrom pathlib import Path\\nimport sqlite3\\nimport shutil\\n\\nDECISIONS=(\'CANDIDATE_FORWARD\',\'AWAITING_COST_REVIEWS\',\'REJECTED\',\'INSUFFICIENT_EVIDENCE\',\'REVIEW_BLOCKED\')\\nCHECKS=(\'PASSED\',\'PENDING\',\'REJECTED\',\'INSUFFICIENT\',\'BLOCKED\')\\nMETHODS=(\'MOMENTUM\',\'MEAN_REVERSION\',\'BREAKOUT\')\\n\\ndef check(value):\\n    if value is None:return \'PENDING\'\\n    if value.get(\'status\')==\'DATASET_CHANGED_REVIEW_UNAVAILABLE\':return \'BLOCKED\'\\n    metrics=[value.get(k,{}) for k in (\'development\',\'review\')]\\n    if any(type(m.get(\'n\')) is not int or m[\'n\']<30 for m in metrics):return \'INSUFFICIENT\'\\n    means=[m.get(\'mean_range_units\') for m in metrics]\\n    if any(type(v) not in (int,float) or not math.isfinite(v) for v in means):return \'BLOCKED\'\\n    if any(v<=0 for v in means):return \'REJECTED\'\\n    return \'PASSED\' if value.get(\'status\')==\'NEEDS_FORWARD_VALIDATION\' else \'BLOCKED\'\\n\\ndef decision_report(trial_id, symbol, created_utc, original, reviews):\\n    if original.get(\'method\') not in METHODS or original.get(\'side\') not in (\'BUY\',\'SELL\'):raise ValueError(\'INVALID_RESEARCH_METHOD\')\\n    states=dict(zip((\'historical\',\'cost2\',\'cost3\'),[check(original),*(check(r) for r in reviews)]))\\n    values=set(states.values())\\n    decision=(\'REJECTED\' if \'REJECTED\' in values else \'INSUFFICIENT_EVIDENCE\' if \'INSUFFICIENT\' in values\\n              else \'REVIEW_BLOCKED\' if \'BLOCKED\' in values else \'AWAITING_COST_REVIEWS\' if \'PENDING\' in values else \'CANDIDATE_FORWARD\')\\n    out=dict(trial_id=trial_id,experiment_utc=created_utc,method=original[\'method\'],side=original[\'side\'],\\n             instrument_id=sha256(str(symbol).encode()).hexdigest()[:24],decision=decision,checks=states,\\n             checks_passed=sum(v==\'PASSED\' for v in states.values()),checks_required=3,\\n             consensus=\'RULE_BASED_CHECKS_NOT_INDEPENDENT_VOTES\',engine=\'PYTHON_H1_RESEARCH\',\\n             live_authorized=False,production_approved=False,independent_holdout=False,\\n             prospective_validation=False,mt5_tester_verified=False)\\n    for key,allowed in [(\'lookback\',(12,24,48)),(\'horizon\',(4,12,24)),(\'threshold\',(.5,1,1.5))]:\\n        if original.get(key) in allowed:out[key]=original[key]\\n    for name in (\'development\',\'review\'):\\n        source=original.get(name,{})\\n        out[name]={}\\n        for key in (\'n\',\'mean_range_units\'):\\n            value=source.get(key)\\n            if type(value) in (int,float) and math.isfinite(value) and abs(value)<100_000_000:out[name][key]=value\\n    return out\\n\\n\\ndef prepare_report_indexes(db):\\n    db.execute(\'PRAGMA temp_store=MEMORY\')\\n    db.execute(\'PRAGMA cache_size=-16384\')\\n    db.execute(\'CREATE INDEX IF NOT EXISTS research_heads_report_id ON research_report_heads(report_id)\')\\n    db.execute(\'CREATE INDEX IF NOT EXISTS research_reports_created ON research_reports(created_utc DESC,id DESC)\')\\n    db.execute(\'CREATE INDEX IF NOT EXISTS research_reports_decision_created ON research_reports(decision,created_utc DESC,id DESC)\')\\n    db.execute(\'CREATE INDEX IF NOT EXISTS research_reports_head_counts ON research_reports(id,decision)\')\\n\\n\\ndef publish_reports(root, trace=None, batch=64):\\n    \\"\\"\\"Process a bounded evidence queue; reconcile archive categories incrementally.\\"\\"\\"\\n    root=Path(root);stamp=datetime.now(timezone.utc).isoformat()\\n    target=root/\'experiment-jobs.sqlite3\'\\n    from katarina.intelligence.research_capacity import research_capacity\\n    if research_capacity(root)[\'status\']!=\'READY\':return 0\\n    with closing(sqlite3.connect(target,timeout=2)) as db:\\n        db.execute(\'CREATE TABLE IF NOT EXISTS research_reports(id TEXT PRIMARY KEY,trial_id TEXT,created_utc TEXT,decision TEXT,report_json TEXT)\')\\n        db.execute(\'CREATE TABLE IF NOT EXISTS research_report_heads(trial_id TEXT PRIMARY KEY,signature TEXT,report_id TEXT,decision TEXT)\')\\n        if \'decision\' not in {r[1] for r in db.execute(\'PRAGMA table_info(research_report_heads)\')}:\\n            db.execute(\'ALTER TABLE research_report_heads ADD COLUMN decision TEXT\')\\n        tables={r[0] for r in db.execute(\\"SELECT name FROM sqlite_master WHERE type=\'table\'\\")}\\n        if not {\'trials\',\'stress_reviews\'}<=tables:return 0\\n        fields=(\'status\',\'development.n\',\'review.n\',\'development.mean_range_units\',\'review.mean_range_units\')\\n        signature=\\"||\'|\'||\\".join(f\\"coalesce(CAST(json_extract({alias}.result_json,\'$.{field}\') AS TEXT),\'MISSING\')\\" for alias in (\'t\',\'s2\',\'s3\') for field in fields)\\n        rows=db.execute(f\\"WITH recent_trials AS (SELECT id FROM trials ORDER BY rowid DESC LIMIT 256), recent_reviews AS (SELECT trial_id FROM stress_reviews ORDER BY rowid DESC LIMIT 256), missing AS (SELECT t.id FROM trials t WHERE NOT EXISTS(SELECT 1 FROM research_report_heads h WHERE h.trial_id=t.id) ORDER BY t.rowid LIMIT 64), pending AS (SELECT id FROM recent_trials UNION SELECT CASE WHEN trial_id LIKE \'COST3:%\' THEN substr(trial_id,7) ELSE trial_id END FROM recent_reviews UNION SELECT id FROM missing) SELECT t.id,t.symbol,t.created_utc,t.result_json,s2.result_json,s3.result_json,{signature} FROM pending p JOIN trials t ON t.id=p.id LEFT JOIN stress_reviews s2 ON s2.trial_id=t.id LEFT JOIN stress_reviews s3 ON s3.trial_id=\'COST3:\'||t.id LEFT JOIN research_report_heads h ON h.trial_id=t.id WHERE h.trial_id IS NULL OR h.signature!=({signature}) ORDER BY t.created_utc DESC LIMIT ?\\",(batch,)).fetchall()\\n        candidates_by_trial={}\\n        try:\\n            cached=json.loads((root/\'research-reports.json\').read_text())\\n            for item in cached.get(\'candidates\',[])[:3]:candidates_by_trial[item[\'trial_id\']]=item\\n        except (OSError,ValueError,KeyError,TypeError):pass\\n        if rows and trace:trace.emit(\'REPORT\',\'STARTED\',action=\'EVIDENCE_DECISION_REPORT\')\\n        with db:\\n            for ident,symbol,created,raw,r2,r3,version in rows:\\n                result=decision_report(ident,symbol,created,json.loads(raw),[json.loads(v) if v else None for v in (r2,r3)])\\n                report_id=sha256((ident+\'|\'+version).encode()).hexdigest()\\n                result.update(id=report_id,reported_utc=stamp)\\n                db.execute(\'INSERT OR IGNORE INTO research_reports VALUES(?,?,?,?,?)\',(report_id,ident,stamp,result[\'decision\'],json.dumps(result,allow_nan=False)))\\n                db.execute(\'INSERT OR REPLACE INTO research_report_heads(trial_id,signature,report_id,decision) VALUES(?,?,?,?)\',(ident,version,report_id,result[\'decision\']))\\n                if result[\'decision\'] in (\'CANDIDATE_FORWARD\',\'AWAITING_COST_REVIEWS\'):candidates_by_trial[ident]=result\\n            # Backfill at most 128 legacy heads; do not scan/sort full report bodies.\\n            legacy=db.execute(\'SELECT trial_id,report_id FROM research_report_heads WHERE decision IS NULL LIMIT 128\').fetchall()\\n            for trial,report_id in legacy:\\n                record=db.execute(\'SELECT decision,report_json FROM research_reports WHERE id=?\',(report_id,)).fetchone()\\n                if record:\\n                    db.execute(\'UPDATE research_report_heads SET decision=? WHERE trial_id=?\',(record[0],trial))\\n                    if record[0] in (\'CANDIDATE_FORWARD\',\'AWAITING_COST_REVIEWS\'):candidates_by_trial[trial]=json.loads(record[1])\\n        if rows and trace:trace.emit(\'REPORT\',\'DONE\',action=\'EVIDENCE_DECISION_REPORT\',count=len(rows))\\n        recent=[]\\n        for (ident,) in db.execute(\'SELECT report_id FROM research_report_heads ORDER BY rowid DESC LIMIT 8\'):\\n            row=db.execute(\'SELECT report_json FROM research_reports WHERE id=?\',(ident,)).fetchone()\\n            if row:recent.append(json.loads(row[0]))\\n        candidates=[]\\n        for trial in candidates_by_trial:\\n            row=db.execute(\'SELECT r.report_json FROM research_report_heads h JOIN research_reports r ON r.id=h.report_id WHERE h.trial_id=?\',(trial,)).fetchone()\\n            if row:\\n                item=json.loads(row[0])\\n                if item[\'decision\'] in (\'CANDIDATE_FORWARD\',\'AWAITING_COST_REVIEWS\'):candidates.append(item)\\n        candidates=sorted(candidates,key=lambda r:r[\'reported_utc\'],reverse=True)[:3]\\n        reviewed=db.execute(\'SELECT COUNT(*) FROM research_report_heads\').fetchone()[0]\\n        remaining=db.execute(\'SELECT COUNT(*) FROM research_report_heads WHERE decision IS NULL\').fetchone()[0]\\n        counts={k:None for k in DECISIONS}\\n        if not remaining:\\n            counts={k:0 for k in DECISIONS}\\n            counts.update(dict(db.execute(\'SELECT decision,COUNT(*) FROM research_report_heads GROUP BY decision\')))\\n        total=db.execute(\'SELECT COUNT(*) FROM trials\').fetchone()[0]\\n        value=dict(schema_version=1,status=\'RESEARCH_REPORTS\',source=\'PERSISTED_RULE_BASED_RESEARCH_REPORTS\',pid=os.getpid(),as_of_utc=datetime.now(timezone.utc).isoformat(),\\n                   reviewed_experiments=reviewed,unreported_experiments=max(0,total-reviewed),counts=counts,counts_pending=remaining,\\n                   recent=recent,candidates=candidates,live_authorized=False,production_approved=False)\\n        temporary=root/\'research-reports.tmp\';temporary.write_text(json.dumps(value,allow_nan=False)+\'\\\\n\',encoding=\'utf-8\');replace_snapshot(temporary,root/\'research-reports.json\')\\n        return len(rows)\\n\\n\\ndef read_reports(root, pid):\\n    \\"\\"\\"Observe durable report records without relabelling their creation time.\\n\\n    A report belongs to its dataset, not to the process that happened to render\\n    the previous JSON file. Re-observe persisted heads read-only after restart.\\n    \\"\\"\\"\\n    import time\\n    if type(pid) is not int or pid <= 0:\\n        return {\'status\':\'NOT_ATTESTED\'}\\n    root=Path(root)\\n    try:\\n        target=(root/\'experiment-jobs.sqlite3\').resolve()\\n        with closing(sqlite3.connect(target.as_uri()+\'?mode=ro\',uri=True,timeout=.25)) as db:\\n            db.execute(\'PRAGMA query_only=ON\')\\n            deadline=time.monotonic()+2\\n            db.set_progress_handler(lambda: int(time.monotonic()>deadline),10000)\\n            db.execute(\'BEGIN\')\\n            join=\'FROM research_report_heads h JOIN research_reports r ON r.id=h.report_id\'\\n            recent=[json.loads(r[0]) for r in db.execute(\'SELECT r.report_json FROM research_reports r INDEXED BY research_reports_created WHERE EXISTS(SELECT 1 FROM research_report_heads h WHERE h.report_id=r.id) ORDER BY r.created_utc DESC,r.id DESC LIMIT 8\')]\\n            candidates=[json.loads(r[0]) for r in db.execute(\\"SELECT r.report_json FROM research_reports r INDEXED BY research_reports_decision_created WHERE r.decision IN (\'CANDIDATE_FORWARD\',\'AWAITING_COST_REVIEWS\') AND EXISTS(SELECT 1 FROM research_report_heads h WHERE h.report_id=r.id) ORDER BY r.created_utc DESC,r.id DESC LIMIT 3\\")]\\n            counts={k:0 for k in DECISIONS}\\n            counts.update(dict(db.execute(\'SELECT r.decision,COUNT(*) FROM research_report_heads h JOIN research_reports r INDEXED BY research_reports_head_counts ON r.id=h.report_id GROUP BY r.decision\')))\\n            total=db.execute(\'SELECT COUNT(*) FROM trials\').fetchone()[0]\\n            latest=recent[0][\'reported_utc\'] if recent else None\\n            return dict(schema_version=1,status=\'RESEARCH_REPORTS\',source=\'PERSISTED_RULE_BASED_RESEARCH_REPORTS\',\\n                snapshot_role=\'READONLY_REPORT_OBSERVATION\',pid=pid,as_of_utc=datetime.now(timezone.utc).isoformat(),\\n                latest_report_utc=latest,reviewed_experiments=sum(counts.values()),\\n                unreported_experiments=max(0,total-sum(counts.values())),counts=counts,\\n                recent=recent,candidates=candidates,live_authorized=False,production_approved=False)\\n    except (sqlite3.Error,OSError,ValueError,KeyError,TypeError):\\n        # Immutable reports remain inspectable while live DB observation is busy.\\n        # Keep the original creation time; only the file verification time is new.\\n        try:\\n            raw=(root/\'research-reports.json\').read_bytes()\\n            if len(raw)>32768:raise ValueError()\\n            cached=json.loads(raw)\\n            stamp=datetime.fromisoformat(cached[\'as_of_utc\'])\\n            if (cached.get(\'status\')!=\'RESEARCH_REPORTS\' or stamp.tzinfo is None\\n                    or (datetime.now(timezone.utc)-stamp).total_seconds() < -30):raise ValueError()\\n            cached[\'producer_pid\']=cached.get(\'pid\')\\n            cached.update(pid=pid,snapshot_role=\'PERSISTED_REPORT_FILE_OBSERVATION\',\\n                          latest_report_utc=cached[\'as_of_utc\'],\\n                          as_of_utc=datetime.now(timezone.utc).isoformat(),\\n                          live_authorized=False,production_approved=False)\\n            return cached\\n        except (OSError,ValueError,KeyError,TypeError):\\n            return {\'status\':\'NOT_ATTESTED\'}\\n", "src/katarina/monitoring/learning_evidence.py": "\\"\\"\\"Technical research counters only; never neural activation or model training attestation.\\"\\"\\"\\nfrom datetime import datetime, timezone\\nimport json\\nfrom pathlib import Path\\nfrom katarina.monitoring.runtime_details import counter, label\\n\\n\\ndef summarize_learning(report):\\n    \\"\\"\\"Keep checkpoint time distinct from the current observation time.\\"\\"\\"\\n    def obj(key):\\n        value = report.get(key)\\n        return value if isinstance(value, dict) else {}\\n    cognition, memory, evolution = obj(\'unified_cognitive_cycle\'), obj(\'neuro_link_memory\'), obj(\'self_evolution_lab\')\\n    def stamp(value):\\n        try:\\n            d = datetime.fromisoformat(value)\\n            return d.isoformat() if d.tzinfo is not None else None\\n        except (ValueError, TypeError):\\n            return None\\n    ledger = label(cognition.get(\'ledger_status\'))\\n    matured, inserted = counter(cognition.get(\'matured_observations\')), counter(memory.get(\'records_inserted\'))\\n    counts = obj(\'quote_journal\').get(\'counts\', {})\\n    virtual = obj(\'virtual_shadow_summary\').get(\'counts\', {})\\n    return dict(\\n        status=\'NO_NEW_MATURED_EVIDENCE\' if ledger == \'ALREADY_LEARNED_NO_REWRITE\'\\n            else \'RESEARCH_REPORTED\',\\n        source=\'CANONICAL_RESEARCH_SNAPSHOT\',\\n        observation_utc=stamp(report.get(\'observed_at_utc\')),\\n        cognitive_as_of_utc=stamp(cognition.get(\'as_of_utc\')),\\n        ledger_status=ledger,\\n        matured_observations=matured, new_matured_observations=0 if ledger==\'ALREADY_LEARNED_NO_REWRITE\' else matured, memory_records_inserted=inserted,\\n        memory_records_considered=counter(memory.get(\'records_considered\')),\\n        shadow_rows_read=counter(evolution.get(\'rows_read\')),\\n        external_models_invoked=counter(evolution.get(\'external_models_invoked\')),\\n        evolution_decision=label(evolution.get(\'decision\')),\\n        no_signal_observations=counter(counts.get(\'NO_SIGNAL\')) if isinstance(counts, dict) else None,\\n        virtual_open=counter(virtual.get(\'OPEN\')) if isinstance(virtual, dict) else None,\\n        neural_activation_measured=False, model_training_verified=False,\\n        improvement_verified=False, live_authorized=False,\\n    )\\n\\n\\ndef read_learning(root, *, observation_utc):\\n    \\"\\"\\"Read an existing bounded JSON snapshot; never open a database or write state.\\"\\"\\"\\n    unknown = dict(status=\'NOT_ATTESTED\', source=\'CANONICAL_RESEARCH_SNAPSHOT\')\\n    try:\\n        with (Path(root) / \'latest.json\').open(\'rb\') as stream:\\n            raw = stream.read(2_000_001)\\n        if len(raw) > 2_000_000:\\n            return unknown\\n        report = json.loads(raw)\\n        if not isinstance(report, dict) or report.get(\'observed_at_utc\') != observation_utc:\\n            return unknown\\n        stamp = datetime.fromisoformat(observation_utc)\\n        age = (datetime.now(timezone.utc) - stamp).total_seconds()\\n        if not 0 <= age <= 180:\\n            return unknown\\n        return summarize_learning(report)\\n    except (OSError, ValueError, TypeError, UnicodeError):\\n        return unknown\\n", "src/katarina/monitoring/research_health.py": "\\"\\"\\"Read-only scheduler evidence; no broker access or writes to research memory.\\"\\"\\"\\nfrom contextlib import closing\\nfrom datetime import datetime,timezone\\nfrom pathlib import Path\\nimport sqlite3,time\\nfrom katarina.intelligence.research_capacity import research_capacity\\nfrom katarina.monitoring.worker_runtime import _read,_fresh\\n\\n_CACHE={}\\nSUPPORT_STATES={\'STARTING\',\'REVIEWING\',\'REVIEW_COMPLETED\',\'WAITING_ELIGIBLE_CANDIDATE\',\'PAUSED_LOW_DISK\',\'PAUSED_STORAGE_BUDGET\',\'RETRY_PENDING\',\'WAITING_BUDGET\',\'NOT_CONFIGURED\',\'HYPOTHESES_SAVED\',\'RETRY_AFTER_COOLDOWN\'}\\n\\n\\ndef read_research_health(root,pid,*,allowed,now=None):\\n    if not allowed:return {\'status\':\'NOT_ATTESTED\'}\\n    root=Path(root);now=now or datetime.now(timezone.utc)\\n    out=dict(status=\'OBSERVED\',pid=pid,as_of_utc=now.isoformat(),capacity=research_capacity(root),\\n             policy=\'BASELINE_ELIGIBLE_ONLY\',review_interval_seconds=15,support=[])\\n    for phase in (\'VALIDATE\',\'VALIDATE3\',\'GEMINI\'):\\n        w=_read(root/(\'worker-\'+phase+\'.json\'))\\n        fresh=w.get(\'pid\')==pid and w.get(\'autonomous\') is True and _fresh(w,now)\\n        out[\'support\'].append(dict(phase=phase,fresh=fresh,status=w.get(\'status\') if fresh and w.get(\'status\') in SUPPORT_STATES else \'UNVERIFIED\'))\\n    key=(str(root),pid);cached=_CACHE.get(key)\\n    if cached and time.monotonic()-cached[0]<15:\\n        out.update(cached[1]);return out\\n    metrics=dict(latest_experiment_utc=None,latest_hypothesis_utc=None,eligible_candidates=None,pending_cost2=None,pending_cost3=None)\\n    try:\\n        with closing(sqlite3.connect((root/\'experiment-jobs.sqlite3\').resolve().as_uri()+\'?mode=ro\',uri=True,timeout=.25)) as db:\\n            db.execute(\'PRAGMA query_only=ON\');deadline=time.monotonic()+1.5;db.set_progress_handler(lambda:int(time.monotonic()>deadline),10000);db.execute(\'BEGIN\')\\n            metrics[\'latest_experiment_utc\']=db.execute(\'SELECT MAX(created_utc) FROM trials\').fetchone()[0]\\n            metrics[\'latest_hypothesis_utc\']=db.execute(\'SELECT MAX(created_utc) FROM gemini_hypotheses\').fetchone()[0]\\n            count,p2,p3=db.execute(\\"SELECT COUNT(*),SUM(NOT EXISTS(SELECT 1 FROM stress_reviews s WHERE s.trial_id=t.id)),SUM(NOT EXISTS(SELECT 1 FROM stress_reviews s WHERE s.trial_id=\'COST3:\'||t.id)) FROM trials t WHERE json_extract(t.result_json,\'$.status\')=\'NEEDS_FORWARD_VALIDATION\'\\").fetchone()\\n            metrics.update(eligible_candidates=count,pending_cost2=p2 or 0,pending_cost3=p3 or 0)\\n    except (sqlite3.Error,OSError,ValueError):pass\\n    _CACHE[key]=(time.monotonic(),metrics)\\n    if len(_CACHE)>8:\\n        _CACHE.pop(next(iter(_CACHE)))\\n    out.update(metrics);return out\\n", "src/katarina/monitoring/public_runtime.py": "\\"\\"\\"Reconstruct a technical-only, freshness-checked view without opening broker or memory.\\"\\"\\"\\nfrom pathlib import Path\\nimport json\\nfrom katarina.intelligence.runtime_evidence import read_runtime\\nfrom katarina.monitoring.agent_projection import project_agent_board\\nfrom katarina.monitoring.activity_trace import read_activity\\nfrom katarina.adapters.owner_dialog_server import public_dashboard_snapshot\\n\\ndef build_public_runtime(root):\\n    root=Path(root)\\n    try:\\n        status=json.loads((root/\'continuous-status.json\').read_text(encoding=\'utf-8\'))\\n    except (OSError,ValueError):\\n        status={}\\n    evidence=read_runtime(root)\\n    board=project_agent_board(evidence,delivery=status.get(\'delivery\',\'UNVERIFIED\'))\\n    activity=read_activity(root)\\n    pid=status.get(\'pid\')\\n    board[\'current_process_pid\']=pid\\n    market_process_matches=evidence.get(\'operational\',{}).get(\'snapshot_pid\')==pid\\n    board[\'snapshot_process_matches\']=bool(type(pid) is int and activity.get(\'pid\')==pid and activity.get(\'fresh\'))\\n    if not market_process_matches:\\n        board[\'result\']=\'BLOCKED\'\\n    if status.get(\'status\') in (\'STOPPED\',\'BLOCKED\'):\\n        board[\'result\']=\'BLOCKED\'\\n    board[\'model\']={\'configured\':status.get(\'model_configured\') is True,\\n                    \'telemetry\':status.get(\'model_telemetry\',{})}\\n    board[\'activity\']=activity\\n    public = public_dashboard_snapshot({\'agent_board\':board})\\n    from katarina.monitoring.learning_evidence import read_learning\\n    from katarina.monitoring.public_research import read_public_research\\n    allowed = board[\'snapshot_process_matches\'] and board.get(\'result\') == \'SNAPSHOT_PASS\'\\n    research_allowed = bool(board[\'snapshot_process_matches\'] and status.get(\'delivery\') == \'DISABLED\'\\n        and status.get(\'live_execution_authorized\') is False and status.get(\'orders_submitted\') == 0\\n        and status.get(\'status\') in (\'WAITING\',\'OBSERVING\',\'DEGRADED\'))\\n    # Sensor completeness and persisted research provenance are separate attestations.\\n    try:\\n        with (root/\'latest.json\').open(\'rb\') as stream:\\n            raw=stream.read(2_000_001)\\n        observation_stamp=json.loads(raw)[\'observed_at_utc\'] if len(raw)<=2_000_000 else None\\n    except (OSError,ValueError,KeyError):\\n        observation_stamp=None\\n    graph, entries = read_public_research(root,observation_stamp) if research_allowed else (\\n        {\'schema_version\':1,\'nodes\':[],\'edges\':[],\'status\':\'NOT_ATTESTED\'},\\n        {\'status\':\'NOT_ATTESTED\',\'positions\':[]})\\n    if research_allowed and graph.get(\'status\')==\'NOT_ATTESTED\':\\n        from katarina.monitoring.public_research import worker_research_runs,graph_from_report\\n        runs=worker_research_runs(root)\\n        if runs:graph=graph_from_report({\'continuous_research_lab\':{\'recent\':runs}})\\n    public_board=public[\'agent_board\']\\n    # Process activity, market completeness and learning are distinct evidence scopes.\\n    from datetime import datetime, timezone\\n    try:\\n        heartbeat_age=(datetime.now(timezone.utc)-datetime.fromisoformat(status[\'heartbeat_utc\'])).total_seconds()\\n    except (KeyError,ValueError,TypeError):\\n        heartbeat_age=float(\'inf\')\\n    public_board[\'telemetry_verified\']=bool(research_allowed and status.get(\'production_execution\') is False\\n                                           and (-30<=heartbeat_age<=180 or activity.get(\'fresh\') is True))\\n    public_board[\'market_snapshot_verified\']=board.get(\'result\')==\'SNAPSHOT_PASS\'\\n    public_board[\'sensor_blockers\']=evidence.get(\'blockers\',[])\\n    public_board[\'learning\']=(read_learning(root,observation_utc=observation_stamp)\\n                              if public_board[\'telemetry_verified\'] else {\'status\':\'NOT_ATTESTED\'})\\n    from katarina.monitoring.research_growth import read_growth\\n    public_board[\'research_growth\']=read_growth(root,pid) if research_allowed else {\'status\':\'NOT_ATTESTED\'}\\n    public_board[\'research_graph\']=graph\\n    from katarina.intelligence.research_reports import read_reports\\n    public_board[\'research_reports\']=read_reports(root,pid) if research_allowed else {\'status\':\'NOT_ATTESTED\'}\\n    from katarina.monitoring.research_lab_status import read_lab_status\\n    public_board[\'research_lab\'] = read_lab_status(root) if research_allowed else {\'status\':\'NOT_ATTESTED\'}\\n    from katarina.intelligence.data_recovery import read_recovery\\n    public_board[\'research_lab\'][\'recovery\']=read_recovery(root,pid) if research_allowed else {\'status\':\'NOT_ATTESTED\'}\\n    public_board[\'research_source_verified\'] = research_allowed and graph.get(\'status\') != \'NOT_ATTESTED\'\\n    public_board[\'entries\']=entries\\n    public_board[\'market_symbols\']=None\\n    public_board[\'operational\']={}\\n    public_board[\'learning\'].pop(\'no_signal_observations\',None)\\n    trace=public_board[\'activity\']\\n    trace[\'events\']=[{k:e[k] for k in (\'seq\',\'at_utc\',\'phase\',\'state\')} for e in trace[\'events\']]\\n    trace[\'current\']=trace[\'events\'][-1] if trace[\'events\'] else None\\n    from katarina.monitoring.worker_runtime import read_worker_runtime\\n    public_board[\'worker_runtime\']=read_worker_runtime(root,pid)\\n    public_board[\'public_scope\']=\'RESEARCH_ENTRY_AND_PNL\'\\n    from katarina.monitoring.pair_activity import read_pair_activity\\n    public_board[\'pair_activity\']=read_pair_activity(root,pid,allowed=public_board.get(\'telemetry_verified\') is True and board[\'snapshot_process_matches\'])\\n    from katarina.monitoring.entry_feed import read_entry_feed\\n    public_board[\'entry_feed\']=read_entry_feed(root,allowed=research_allowed)\\n    from katarina.monitoring.position_feed import read_position_feed\\n    public_board[\'position_feed\']=read_position_feed(root,allowed=research_allowed)\\n    from katarina.monitoring.research_health import read_research_health\\n    public_board[\'research_health\']=read_research_health(root,pid,allowed=research_allowed)\\n    return public\\n", "tests/unit/test_research_scheduler.py": "from contextlib import closing\\nfrom pathlib import Path\\nfrom unittest.mock import patch\\nimport json,sqlite3,tempfile,unittest,threading\\nfrom katarina.intelligence.autonomous_research import ResearchPool,preserve_dataset\\nfrom katarina.monitoring.research_health import read_research_health\\n\\nclass Trace:\\n    def __init__(self):self.events=[]\\n    def emit(self,*args,**kw):self.events.append((args,kw))\\n\\nclass ResearchSchedulerTests(unittest.TestCase):\\n    def setup_db(self,root):\\n        with closing(sqlite3.connect(root/\'experiment-jobs.sqlite3\')) as db,db:\\n            db.execute(\'CREATE TABLE trials(id TEXT PRIMARY KEY,symbol,digest,created_utc,result_json)\')\\n            db.execute(\'CREATE TABLE gemini_hypotheses(created_utc,result_json)\')\\n            db.execute(\'CREATE TABLE stress_reviews(trial_id TEXT PRIMARY KEY,created_utc,result_json)\')\\n            rows=[[1000+i*3600,10,12,8,10] for i in range(512)]\\n            from hashlib import sha256\\n            digest=sha256(json.dumps(rows,separators=(\',\',\':\')).encode()).hexdigest();preserve_dataset(db,digest,rows)\\n            for ident,status in [(\'bad\',\'REJECTED_IN_HISTORICAL_REVIEW\'),(\'small\',\'INSUFFICIENT_SAMPLES\'),(\'good\',\'NEEDS_FORWARD_VALIDATION\')]:\\n                db.execute(\'INSERT INTO trials VALUES(?,?,?,?,?)\',(ident,\'EURUSD\',digest,\'2026-10-20T00:00:00+00:00\',json.dumps(dict(status=status))))\\n\\n    def test_only_viable_trials_are_reviewed_once_per_cost_level(self):\\n        with tempfile.TemporaryDirectory() as d:\\n            root=Path(d);self.setup_db(root);trace=Trace();pool=ResearchPool(root,trace)\\n            with patch(\'katarina.intelligence.research_capacity.research_capacity\',return_value={\'status\':\'READY\'}),patch(\'katarina.intelligence.autonomous_research.cost_review\',return_value={\'status\':\'NEEDS_FORWARD_VALIDATION\'}) as evaluate:\\n                self.assertTrue(pool.review_one(2));self.assertTrue(pool.review_one(3))\\n                self.assertFalse(pool.review_one(2));self.assertFalse(pool.review_one(3));self.assertEqual(evaluate.call_count,2)\\n            with closing(sqlite3.connect(root/\'experiment-jobs.sqlite3\')) as db:\\n                self.assertEqual({r[0] for r in db.execute(\'SELECT trial_id FROM stress_reviews\')},{\'good\',\'COST3:good\'})\\n            self.assertEqual(pool.review_states[2][\'status\'],\'WAITING_ELIGIBLE_CANDIDATE\')\\n            h=read_research_health(root,123,allowed=True);self.assertEqual(h[\'eligible_candidates\'],1);self.assertEqual(h[\'pending_cost2\'],0)\\n\\n    def test_low_disk_blocks_reviews_and_model_calls_before_database_writes(self):\\n        with tempfile.TemporaryDirectory() as d:\\n            root=Path(d);model=unittest.mock.Mock();pool=ResearchPool(root,Trace(),model)\\n            with patch(\'katarina.intelligence.research_capacity.research_capacity\',return_value={\'status\':\'PAUSED_LOW_DISK\'}):\\n                self.assertFalse(pool.review_one(2));self.assertFalse(pool.model_once())\\n            self.assertFalse((root/\'experiment-jobs.sqlite3\').exists());model.complete.assert_not_called()\\n            self.assertEqual(pool.review_states[2][\'status\'],\'PAUSED_LOW_DISK\')\\n", "tests/unit/test_learning_evidence.py": "\\"\\"\\"Learning evidence must report inactivity and cached checkpoint time honestly.\\"\\"\\"\\nfrom datetime import datetime, timedelta, timezone\\nimport json\\nfrom pathlib import Path\\nimport tempfile\\nimport unittest\\nfrom katarina.monitoring.learning_evidence import summarize_learning, read_learning\\n\\n\\nclass LearningEvidenceTests(unittest.TestCase):\\n    def fixture(self):\\n        return {\\n            \'observed_at_utc\': datetime.now(timezone.utc).isoformat(),\\n            \'unified_cognitive_cycle\': {\'as_of_utc\': \'2026-10-16T02:24:27+00:00\',\\n                \'ledger_status\': \'ALREADY_LEARNED_NO_REWRITE\', \'matured_observations\': 0},\\n            \'neuro_link_memory\': {\'records_inserted\': 0, \'records_considered\': 0},\\n            \'self_evolution_lab\': {\'rows_read\': 1, \'external_models_invoked\': 0,\\n                \'decision\': \'WAIT_FOR_VERIFIED_EVIDENCE\'},\\n            \'quote_journal\': {\'counts\': {\'NO_SIGNAL\': 3377}},\\n            \'virtual_shadow_summary\': {\'counts\': {\'OPEN\': 1}},\\n            \'account_login\': \'SECRET_SENTINEL\',\\n        }\\n\\n    def test_no_new_evidence_is_not_presented_as_learning(self):\\n        report = self.fixture()\\n        result = summarize_learning(report)\\n        self.assertEqual(result[\'status\'], \'NO_NEW_MATURED_EVIDENCE\')\\n        self.assertEqual(result[\'memory_records_inserted\'], 0)\\n        self.assertEqual(result[\'shadow_rows_read\'], 1)\\n        self.assertNotEqual(result[\'cognitive_as_of_utc\'], result[\'observation_utc\'])\\n        self.assertFalse(result[\'improvement_verified\'])\\n        self.assertFalse(result[\'neural_activation_measured\'])\\n        self.assertNotIn(\'SECRET_SENTINEL\', json.dumps(result))\\n\\n    def test_cumulative_matured_count_does_not_become_new_learning(self):\\n        report=self.fixture();report[\'unified_cognitive_cycle\'][\'matured_observations\']=15\\n        result=summarize_learning(report)\\n        self.assertEqual(result[\'status\'],\'NO_NEW_MATURED_EVIDENCE\')\\n        self.assertEqual(result[\'matured_observations\'],15)\\n        self.assertEqual(result[\'new_matured_observations\'],0)\\n\\n    def test_snapshot_must_match_validated_observation_and_remain_fresh(self):\\n        with tempfile.TemporaryDirectory() as root:\\n            report = self.fixture()\\n            path = Path(root) / \'latest.json\'\\n            path.write_text(json.dumps(report), encoding=\'utf-8\')\\n            self.assertEqual(read_learning(root, observation_utc=report[\'observed_at_utc\'])[\'status\'],\\n                             \'NO_NEW_MATURED_EVIDENCE\')\\n            self.assertEqual(read_learning(root, observation_utc=\'mismatch\')[\'status\'], \'NOT_ATTESTED\')\\n            report[\'observed_at_utc\'] = (datetime.now(timezone.utc)-timedelta(seconds=181)).isoformat()\\n            path.write_text(json.dumps(report), encoding=\'utf-8\')\\n            self.assertEqual(read_learning(root, observation_utc=report[\'observed_at_utc\'])[\'status\'], \'NOT_ATTESTED\')\\n            path.write_bytes(b\'x\'*2_000_001)\\n            self.assertEqual(read_learning(root, observation_utc=report[\'observed_at_utc\'])[\'status\'], \'NOT_ATTESTED\')\\n\\n    def test_invalid_counters_do_not_become_progress(self):\\n        report = self.fixture()\\n        report[\'neuro_link_memory\'][\'records_inserted\'] = True\\n        report[\'self_evolution_lab\'][\'external_models_invoked\'] = -1\\n        result = summarize_learning(report)\\n        self.assertIsNone(result[\'memory_records_inserted\'])\\n        self.assertIsNone(result[\'external_models_invoked\'])\\n"}');EXPECTED=json.loads('{"src/katarina/intelligence/autonomous_research.py": "adad4ffb276a7471a55d62c76f1dc567433f9e4b9ec6546931f37dbaac49f648", "src/katarina/intelligence/research_reports.py": "213ae4c7edf920e895d10461babbb4680b6c72c05b1c8babb450004f487fd665", "src/katarina/monitoring/learning_evidence.py": "712f72e33196bd7e6703debbeed5a0344775ada00b9036b96b34e89b8fb3b504", "src/katarina/monitoring/public_runtime.py": "c7a9471d54c39b7593fcc1af492e402880bd6d761682955d25fa35f3811209e1"}')
